    $forms=new FormRepository($database);$fields=new FormFieldRepository($database);$submissions=new FormSubmissionRepository($database);$definition=new FormDefinitionService($database,$forms,$fields,new FormDefinitionValidator());$lifecycle=new FormSubmissionLifecycleService($database,$forms,$fields,$submissions,new SubmissionValueValidator());
