    $form=$definition->create(['name'=>' Contact form ','status'=>'published','fields'=>[$field('message','textarea',2,['is_required'=>true,'min_length'=>2,'max_length'=>100]),$select,$field('email','email',0,['is_required'=>true,'max_length'=>190]),$field('agree','checkbox',3,['is_required'=>true])]]);
    $assert($form->name()==='Contact form'&&$form->status()==='published','Form create normalizes name and stores state.');$ordered=$fields->forForm($form->id());$assert(array_map(fn(FormField $item)=>$item->key(),$ordered)===['email','topic','message','agree'],'Fields use deterministic sort order.');$assert(array_map(fn(FormFieldOption $item)=>$item->value(),$ordered[1]->options())===['sales','support'],'Options use deterministic sort order.');
    $reject(fn()=>$definition->create(['name'=>'', 'status'=>'draft','fields'=>[]]),'Empty form name is rejected.');$reject(fn()=>$definition->create(['name'=>str_repeat('x',151),'status'=>'draft','fields'=>[]]),'Overlong form name is rejected.');$reject(fn()=>$definition->create(['name'=>"bad\nname",'status'=>'draft','fields'=>[]]),'Control characters in form name are rejected.');$reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('bad key','text',0)]]),'Malformed field key is rejected.');$reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','unknown',0)]]),'Unknown field type is rejected.');$reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','text',0),$field('a','text',1)]]),'Duplicate field key is rejected.');$reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','text',0),$field('b','text',0)]]),'Duplicate field order is rejected.');
    $reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[
