    $reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','select',0)]]),'Select without options is rejected.');$reject(fn()=>$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','text',0,['min_length'=>4,'max_length'=>2])]]),'Inconsistent length constraints are rejected.');
    $submission=$lifecycle->persist($form->id(),['email'=>' TEST@EXAMPLE.TEST ','topic'=>'support','message'=>'Hello','agree'=>'1']);$assert($submission->status()==='new'&&count($submission->values())===4,'Submission starts new with all normalized values.');$values=[];foreach($submission->values() as $value)$values[$value->fieldKey()]=$value;$assert($values['email']->valueText()==='test@example.test'&&$values['topic']->valueLabel()==='Support'&&$values['agree']->valueText()==='1','Email, select snapshot, and checkbox normalization passed.');
    $reject(fn()=>$lifecycle->persist($form->id(),['email'=>'bad','topic'=>'support','message'=>'Hello','agree'=>'1']),'Invalid email is rejected.');$reject(fn()=>$lifecycle->persist($form->id(),['email'=>'x@example.test','topic'=>'bad','message'=>'Hello','agree'=>'1']),'Unknown select option is rejected.');$reject(fn()=>$lifecycle->persist($form->id(),['email'=>'x@example.test','topic'=>'sales','message'=>'x','agree'=>'1']),'Minimum length is enforced.');$reject(fn()=>$lifecycle->persist($form->id(),['email'=>'x@example.test','topic'=>'sales','message'=>'Hello','agree'=>'0']),'Required checkbox is enforced.');$reject(fn()=>$lifecycle->persist($form->id(),['email'=>'x@example.test','topic'=>'sales','message'=>'Hello','agree'=>'1','unknown'=>'x']),'Unknown submission key is rejected.');
    $reviewed=$lifecycle->markReviewed($submission->id());$assert($reviewed->status()==='reviewed','Review lifecycle transition succeeds.');$oldLabel=$values['topic']->fieldLabel();$definition->update($form->id(),['name'=>'Contact form','status'=>'published','fields'=>[$field('message','textarea',2,['is_required'=>true,'min_length'=>2,'max_length'=>100]),$field('topic','select',1,['is_required'=>true,'label'=>'New topic label','options'=>[['option_value'=>'support','option_label'=>'New support','sort_order'=>0]]]),$field('email','email',0,['is_required'=>true,'max_length'=>190]),$field('agree','checkbox',3,['is_required'=>true])]],$form->updatedAt());$historic=$submissions->findById($submission->id());$historicValues=[];foreach($historic->values() as $value)$historicValues[$value->fieldKey()]=$value;$assert($historicValues['topic']->fieldLabel()===$oldLabel&&$historicValues['topic']->valueLabel()==='Support','Definition edit does not rewrite snapshots.');
    $freshForm=$forms->findById($form->id());$definition->update($form->id(),['name'=>'Contact form','status'=>'published','fields'=>[$field('message','textarea',2,['is_required'=>true,'min_length'=>2,'max_length'=>100]),$field('email','email',0,['is_required'=>true,'max_length'=>190]),$field('agree','checkbox',3,['is_required'=>true])]],$freshForm->updatedAt());$historic=$submissions->findById($submission->id());foreach($historic->values() as $value)if($value->fieldKey()==='topic')$assert($value->fieldId()===null&&$value->fieldLabel()===$oldLabel,'Removed field preserves nullable provenance and snapshots.');
