    $connection->beginTransaction();$draft=$definition->create(['name'=>'Nested','status'=>'draft','fields'=>[]]);$assert($connection->inTransaction(),'Nested success retains caller transaction.');try{$definition->create(['name'=>'Bad','status'=>'draft','fields'=>[$field('a','text',0),$field('b','text',0)]]);}catch(InvalidArgumentException){}$assert($connection->inTransaction(),'Nested validation failure retains caller transaction.');$connection->rollBack();$assert($forms->findById($draft->id())===null,'Caller rollback removes nested write.');
    $lifecycle->delete($submission->id());$assert($submissions->findById($submission->id())===null&&(int)$connection->query('SELECT COUNT(*) FROM form_submission_values')->fetchColumn()===0,'Hard deletion cascades submission values.');
